import json
import csv

def get_cvss_score(vuln_data):
    """Extract CVSS v3 score with source priority: NVD > GHSA > RedHat."""
    cvss = vuln_data.get('CVSS', {})
    for source in ['nvd', 'ghsa', 'redhat']:
        if source in cvss:
            score = cvss[source].get('V3Score')
            if score is not None:
                return score
    return 'N/A'

def generate_report(json_input, csv_output):
    try:
        with open(json_input, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except Exception as e:
        print(f"Error reading JSON: {e}")
        return

    vulnerabilities = []
    severity_filter = ['HIGH', 'CRITICAL']

    if 'Results' in data:
        for result in data['Results']:
            if 'Vulnerabilities' in result:
                for vuln in result['Vulnerabilities']:
                    severity = vuln.get('Severity', 'UNKNOWN')
                    if severity in severity_filter:
                        record = {
                            "Package": vuln.get('PkgName'),
                            "Version": vuln.get('InstalledVersion'),
                            "CVE_ID": vuln.get('VulnerabilityID'),
                            "Severity": severity,
                            "CVSS_Score": get_cvss_score(vuln),
                            "Fixed_Version": vuln.get('FixedVersion', 'N/A'),
                            "Title": vuln.get('Title', 'No description'),
                            "Url": vuln.get('PrimaryURL', '')
                        }
                        vulnerabilities.append(record)

    headers = ["Package", "Version", "CVE_ID", "Severity", "CVSS_Score", "Fixed_Version", "Title", "Url"]

    try:
        with open(csv_output, 'w', newline='', encoding='utf-8') as f:
            writer = csv.DictWriter(f, fieldnames=headers)
            writer.writeheader()
            writer.writerows(vulnerabilities)
        print(f"Successfully generated {csv_output} with {len(vulnerabilities)} vulnerabilities.")
    except Exception as e:
        print(f"Error writing CSV: {e}")

if __name__ == "__main__":
    generate_report('/root/trivy_report.json', '/root/security_audit.csv')

